  Future<String> _validateInjection(int tabId, String code) async {
    final tab = await _chrome.tabs.get(tabId);
    final page = await pageClassifier(tabId, tab.url);
    final decision = _injection.validateJs(code: code, page: page);
    if (!decision.allowed) {
