        if (!decision.requiresApproval) continue;
        final explanation = exfilGate.explain(action, decision);
        if (exfilAsk == null || !await exfilAsk(spec.$1, u, explanation)) {
          throw BridgePathException('approval_required', explanation);
        }
      }
    }
