  ToolExecutionResult _hardenedListJson(
    Object? payload, {
    required String source,
  }) {
    final text = _redactor.redact(jsonEncode(payload));
    return ToolExecutionResult.text(
      quarantinePageContent(source: source, content: text),
    );
  }

