Future<ToolExecutionResult> _readingList(Map<String, dynamic> args) async {
  switch (_optStr(args, 'mode') ?? 'list') {
    case 'list':
      final entries = await _chrome.readingList.query(
        title: _optStr(args, 'title'),
        url: _optStr(args, 'url'),
