Future<void> registerBridgeTools(
  ToolRegistry registry,
  ChromeApi chrome, {
  BridgeRiskAsk? riskAsk,
  BridgeFirstCall? onFirstCall,
  Set<String>? visitedOrigins,
  BridgeExfilAsk? exfilAsk,
}) async {
  final bridge = chrome.bridge;
