  while (last != null && last.state == 'in_progress') {
    _enforceCap(last);   // hmm async cancel
    if (DateTime.now().isAfter(deadline)) break;
    await Future<void>.delayed(step);
    last = await _findDownload(id);
  }
  // Final observation: a complete-but-over-cap item is reported
  // honestly rather than as a success...
  return last;
