  group('download tool (gh-1630 F2′)', () {
    (ToolRegistry, FakeChrome) dlReg(DownloadProbe? probe) {
      final c = FakeChrome();
      final surface = BrowserApiToolSurface(c, downloadProbe: probe);
      return (ToolRegistry()..registerAll(surface.tools()), c);
